CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public.campus_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),kind text NOT NULL CHECK(kind IN ('Complaint','Lost','Found','Feedback')),title text NOT NULL CHECK(char_length(title) BETWEEN 3 AND 150),description text NOT NULL CHECK(char_length(description) BETWEEN 5 AND 3000),category text NOT NULL DEFAULT 'Other',department text NOT NULL DEFAULT '',photo_path text,status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Assigned','In progress','Resolved')),rating integer CHECK(rating BETWEEN 1 AND 5),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.campus_reports TO authenticated; GRANT ALL ON public.campus_reports TO service_role;
ALTER TABLE public.campus_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "visible reports" ON public.campus_reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR kind IN ('Lost','Found') OR public.campus_capability('admin'));
CREATE POLICY "own reports create" ON public.campus_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Open' AND department='');
CREATE POLICY "own or approved update" ON public.campus_reports FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.campus_capability('admin')) WITH CHECK(user_id=auth.uid() OR public.campus_capability('admin'));
CREATE FUNCTION public.guard_campus_report() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NOT public.campus_capability('admin') THEN IF (NEW.user_id,NEW.kind,NEW.title,NEW.description,NEW.category,NEW.department,NEW.photo_path,NEW.status,NEW.created_at) IS DISTINCT FROM (OLD.user_id,OLD.kind,OLD.title,OLD.description,OLD.category,OLD.department,OLD.photo_path,OLD.status,OLD.created_at) THEN RAISE EXCEPTION 'Only approved management can update report progress'; END IF; IF OLD.status<>'Resolved' AND OLD.kind<>'Feedback' THEN RAISE EXCEPTION 'Rate only resolved reports'; END IF; END IF; IF TG_OP='UPDATE' AND (NEW.status,NEW.department) IS DISTINCT FROM (OLD.status,OLD.department) THEN INSERT INTO public.campus_notifications(user_id,title,body,kind) VALUES(NEW.user_id,NEW.title,NEW.status || CASE WHEN NEW.department<>'' THEN ' · '||NEW.department ELSE '' END,'Complaint update'); END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_campus_report BEFORE UPDATE ON public.campus_reports FOR EACH ROW EXECUTE FUNCTION public.guard_campus_report();
CREATE TABLE public.item_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES public.campus_reports(id),user_id uuid NOT NULL DEFAULT auth.uid(),evidence text NOT NULL CHECK(char_length(evidence) BETWEEN 10 AND 2000),status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(report_id,user_id));
GRANT SELECT,INSERT,UPDATE ON public.item_claims TO authenticated; GRANT ALL ON public.item_claims TO service_role;
ALTER TABLE public.item_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY "private claims read" ON public.item_claims FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.campus_capability('admin'));
CREATE POLICY "claim found item" ON public.item_claims FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Pending' AND EXISTS(SELECT 1 FROM public.campus_reports WHERE id=report_id AND kind='Found' AND status<>'Resolved'));
CREATE POLICY "approve claims" ON public.item_claims FOR UPDATE TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin'));
CREATE TABLE public.campus_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 150),category text NOT NULL CHECK(category IN ('Laboratory','Seminar hall','Classroom','Study room','Other')),capacity integer NOT NULL DEFAULT 1 CHECK(capacity>0),location text NOT NULL DEFAULT '',available boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE ON public.campus_resources TO authenticated; GRANT ALL ON public.campus_resources TO service_role;
ALTER TABLE public.campus_resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY "resources read" ON public.campus_resources FOR SELECT TO authenticated USING(true);
CREATE POLICY "resources manage" ON public.campus_resources FOR ALL TO authenticated USING(public.campus_capability('admin')) WITH CHECK(public.campus_capability('admin'));
CREATE TABLE public.resource_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),resource_id uuid NOT NULL REFERENCES public.campus_resources(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,purpose text NOT NULL CHECK(char_length(purpose) BETWEEN 3 AND 500),status text NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Confirmed','Cancelled')),created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT valid_booking_interval CHECK(ends_at>starts_at),EXCLUDE USING gist(resource_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status='Confirmed'));
GRANT SELECT,INSERT,UPDATE ON public.resource_bookings TO authenticated; GRANT ALL ON public.resource_bookings TO service_role;
ALTER TABLE public.resource_bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own bookings" ON public.resource_bookings FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.campus_capability('admin'));
CREATE POLICY "reserve available resource" ON public.resource_bookings FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='Confirmed' AND EXISTS(SELECT 1 FROM public.campus_resources WHERE id=resource_id AND available));
CREATE POLICY "cancel own booking" ON public.resource_bookings FOR UPDATE TO authenticated USING(user_id=auth.uid() OR public.campus_capability('admin')) WITH CHECK(status='Cancelled');
CREATE FUNCTION public.guard_booking() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.starts_at<=now() THEN RAISE EXCEPTION 'Choose a future booking time'; END IF; ELSE IF (NEW.id,NEW.user_id,NEW.resource_id,NEW.starts_at,NEW.ends_at,NEW.purpose,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.resource_id,OLD.starts_at,OLD.ends_at,OLD.purpose,OLD.created_at) THEN RAISE EXCEPTION 'Only cancellation is permitted'; END IF; END IF; INSERT INTO public.campus_notifications(user_id,title,body,kind) VALUES(NEW.user_id,'Resource booking '||lower(NEW.status),(SELECT name FROM public.campus_resources WHERE id=NEW.resource_id)||' · '||NEW.starts_at::text,'Booking'); RETURN NEW; END $$;
CREATE TRIGGER guard_booking BEFORE INSERT OR UPDATE ON public.resource_bookings FOR EACH ROW EXECUTE FUNCTION public.guard_booking();
CREATE FUNCTION public.resource_availability(resource uuid,from_time timestamptz,to_time timestamptz) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT to_time>from_time AND EXISTS(SELECT 1 FROM public.campus_resources WHERE id=resource AND available) AND NOT EXISTS(SELECT 1 FROM public.resource_bookings WHERE resource_id=resource AND status='Confirmed' AND starts_at<to_time AND ends_at>from_time) $$;
REVOKE ALL ON FUNCTION public.resource_availability(uuid,timestamptz,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.resource_availability(uuid,timestamptz,timestamptz) TO authenticated;
CREATE TABLE public.campus_schedule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 150),kind text NOT NULL CHECK(kind IN ('Class','Examination','Faculty')),location text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reminder_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.campus_schedule TO authenticated; GRANT ALL ON public.campus_schedule TO service_role;
ALTER TABLE public.campus_schedule ENABLE ROW LEVEL SECURITY;
CREATE POLICY "personal timetable" ON public.campus_schedule FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY "upload report photo" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='campus-reports' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "read report photo" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='campus-reports' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.campus_capability('admin') OR EXISTS(SELECT 1 FROM public.campus_reports r WHERE r.photo_path=name AND r.kind IN ('Lost','Found'))));
CREATE POLICY "remove own report photo" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='campus-reports' AND (storage.foldername(name))[1]=auth.uid()::text);